#include <cstring>
using namespace std;

int main() {
    long int K;
    scanf("%ld", &K);
    char palabra[100005];
    scanf("%s", palabra);

    int lon = strlen(palabra); // Optimized by using strlen

    if (lon > K) {
        printf("%.*s...\n", (int)K, palabra);
    } else {
        printf("%s\n", palabra);
    }
    return 0;
}

